def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
# Test the key question: is every output-2 either original seed or reachable from seed via orthogonal moves
# through EMPTY cells ONLY, i.e., flood fill of empty cells?
for n in [1,2,3]:
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    seeds=[(i,j) for i in range(len(gi)) for j in range(len(gi[0])) if gi[i][j]==2]
    s=seeds[0]; H=len(gi); W=len(gi[0])
    # BFS over cells !=8, allowing through 0 and 2
    from collections import deque
    seen=set([s]); q=deque([s])
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
